@Testcontainers
class RedisVectorStoreIT extends BaseVectorStoreTests {

    @Container
    static RedisStackContainer redisContainer = new RedisStackContainer(RedisStackContainer.DEFAULT_IMAGE_NAME.withTag(RedisStackContainer.DEFAULT_TAG));

    // Use host and port explicitly since getRedisURI() might not be consistent
    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner().withConfiguration(AutoConfigurations.of(DataRedisAutoConfiguration.class)).withUserConfiguration(TestApplication.class).withPropertyValues("spring.data.redis.url=" + redisContainer.getRedisURI()).withPropertyValues("spring.data.redis.client-type=jedis");

    List<Document> documents = List.of(new Document("1", getText("classpath:/test/data/spring.ai.txt"), Map.of("meta1", "meta1")), new Document("2", getText("classpath:/test/data/time.shelter.txt"), Map.of()), new Document("3", getText("classpath:/test/data/great.depression.txt"), Map.of("meta2", "meta2")));

    public static String getText(String uri) {
        var resource = new DefaultResourceLoader().getResource(uri);
        try {
            return resource.getContentAsString(StandardCharsets.UTF_8);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    @BeforeEach
    void cleanDatabase() {
        this.contextRunner.run(context -> context.getBean(RedisVectorStore.class).getJedis().flushAll());
    }

    @Override
    protected void executeTest(Consumer<VectorStore> testFunction) {
        this.contextRunner.run(context -> {
            VectorStore vectorStore = context.getBean(VectorStore.class);
            testFunction.accept(vectorStore);
        });
    }

    @Test
    void ensureIndexGetsCreated() {
