    @Test
    void searchWithFilters() throws InterruptedException {
        this.contextRunner.run(context -> {
            VectorStore vectorStore = context.getBean(VectorStore.class);
            var bgDocument = new Document("The World is Big and Salvation Lurks Around the Corner", Map.of("country", "BG", "year", 2020));
            var nlDocument = new Document("The World is Big and Salvation Lurks Around the Corner", Map.of("country", "NL"));
            var bgDocument2 = new Document("The World is Big and Salvation Lurks Around the Corner", Map.of("country", "BG", "year", 2023));
            vectorStore.add(List.of(bgDocument, nlDocument, bgDocument2));
            List<Document> results = vectorStore.similaritySearch(SearchRequest.builder().query("The World").topK(5).build());
            assertThat(results).hasSize(3);
            results = vectorStore.similaritySearch(SearchRequest.builder().query("The World").topK(5).similarityThresholdAll().filterExpression("country == 'NL'").build());
            assertThat(results).hasSize(1);
            assertThat(results.get(0).getId()).isEqualTo(nlDocument.getId());
            results = vectorStore.similaritySearch(SearchRequest.builder().query("The World").topK(5).similarityThresholdAll().filterExpression("country == 'BG'").build());
            assertThat(results).hasSize(2);
            assertThat(results.get(0).getId()).isIn(bgDocument.getId(), bgDocument2.getId());
            assertThat(results.get(1).getId()).isIn(bgDocument.getId(), bgDocument2.getId());
            results = vectorStore.similaritySearch(SearchRequest.builder().query("The World").topK(5).similarityThresholdAll().filterExpression("country == 'BG' && year == 2020").build());
            assertThat(results).hasSize(1);
            assertThat(results.get(0).getId()).isEqualTo(bgDocument.getId());
            results = vectorStore.similaritySearch(SearchRequest.builder().query("The World").topK(5).similarityThresholdAll().filterExpression("NOT(country == 'BG' && year == 2020)").build());
            assertThat(results).hasSize(2);
            assertThat(results.get(0).getId()).isIn(nlDocument.getId(), bgDocument2.getId());
            assertThat(results.get(1).getId()).isIn(nlDocument.getId(), bgDocument2.getId());
        });
    }

